def rl2000_dual_beam_pattern():
    """Typical RL-2000 LOW/HIGH diagrams digitized from Y7252 figures.

    These curves are intended as a built-in engineering approximation only.
    Exact site/antenna measurement data should be imported when available.
    """
    low = AntennaPattern('RL-2000 LOW · Y7252 typical',
                         _RL2000_ANGLES_DEG.copy(), _RL2000_LOW_DB.copy())
    high = AntennaPattern('RL-2000 HIGH · Y7252 typical',
                          _RL2000_ANGLES_DEG.copy(), _RL2000_HIGH_DB.copy())
    return AntennaPatternPair(
        'RL-2000 dual beam · Y7252 typical', low, high,
        low_peak_dbi=34.3, high_peak_dbi=33.3,
        source_note='Digitized from Y7252 typical elevation diagrams; LOW Tx/Rx, HIGH Rx-only')

def slant_distance(distance, height, antenna_amsl, k):
    radius = EARTH_RADIUS * k
    theta = np.asarray(distance) / radius
    r0, r1 = radius + antenna_amsl, radius + np.asarray(height)
    return np.sqrt(np.maximum(0.0, r0*r0 + r1*r1 - 2*r0*r1*np.cos(theta)))

def pattern_range_factor(pattern, elevation, c, beam_mode=None):
    if isinstance(pattern, AntennaPatternPair):
        return pattern.range_factor(elevation, c.antenna_tilt_deg,
                                    beam_mode or c.beam_mode)
    return pattern.range_factor(elevation, c.antenna_tilt_deg)


def pattern_allows(distance, height, antenna_amsl, c, pattern, beam_mode=None):
    elevation = apparent_angle(distance, height, antenna_amsl, c.k)
    limit = c.csc_range_km * 1000 * pattern_range_factor(
        pattern, elevation, c, beam_mode)
    return (elevation >= np.deg2rad(c.min_elev)) & (elevation <= np.deg2rad(c.max_elev)) & \
           (slant_distance(distance, height, antenna_amsl, c.k) <= limit + 1e-6)

def csc_upper(distance, antenna, c):
    """Exact upper-height intersection of slant sphere and tangent-height cap.

    L <= Lref and L*sin(e) <= Lref*sin(e_ref) are equivalent to the
    clipped cosecant range envelope. Heights use the same effective Earth
    and surface distance as the terrain model (not a flat-Earth sketch).
    """
    radius = EARTH_RADIUS * c.k
    theta = np.asarray(distance) / radius
    r0 = radius + antenna
    limit = c.csc_range_km * 1000
    discriminant = limit**2 - (r0 * np.sin(theta))**2
    sphere = r0 * np.cos(theta) + np.sqrt(np.maximum(discriminant, 0)) - radius
    ceiling = (r0 + limit * np.sin(np.deg2rad(c.csc_ref_deg))) / np.cos(theta) - radius
    return np.where(discriminant >= 0, np.minimum(sphere, ceiling), -np.inf)

def status_at_height(result, height_m, reference='AMSL'):
    target = height_m if reference == 'AMSL' else result['terrain'] + height_m
    visible = (target >= result['lower'] - 1e-6) & (target <= result['upper'] + 1e-6)
    pattern = result.get('antenna_pattern')
    if result['config'].csc_enabled:
        if pattern is not None:
            visible &= pattern_allows(result['distance'][None, :], target, result['antenna'],
                                      result['config'], pattern)
        else:
            visible &= csc_allows(result['distance'][None, :], target, result['antenna'],
                                  result['config'])
    return np.where(result['known'], visible.astype(float), np.nan)

def solve(c, terrain, site_height, antenna_pattern=None):
    az, distance = axes(c)
    if c.radar_mode == 'PAR-NG' and (not c.csc_enabled or not isinstance(antenna_pattern, ParScanPattern)):
        raise ValueError('PAR-NG vyžaduje zapnutý diagram a načtený 3D PAR diagram.')
    if c.radar_mode == 'SSR' and (not c.csc_enabled or not isinstance(antenna_pattern, GenericSSRPattern)):
        raise ValueError('SSR vyžaduje zapnutý obecný SSR model.')
    terrain = np.asarray(terrain, dtype=float)
    if terrain.shape != (len(az), len(distance)) or not np.isfinite(site_height):
        raise ValueError('Chybí výška stanoviště nebo rozměry terénu nesouhlasí.')
    antenna = site_height + c.antenna_agl
    valid = np.isfinite(terrain)
    # A data gap makes this and every farther point on that radial unknown.
    known = np.logical_and.accumulate(valid, axis=1)
    angles = apparent_angle(distance, np.where(valid, terrain, 0), antenna, c.k)
    horizon = np.maximum.accumulate(np.where(valid, angles, -np.inf), axis=1)
    lower_angle = np.maximum(horizon, np.deg2rad(c.min_elev))
    lower = height_at_angle(distance, lower_angle, antenna, c.k)
    # `upper` is always the purely geometric upper elevation bound.
    # Antenna range/gain restrictions are applied separately to visibility so
    # the meaning of this exported field does not change with antenna mode.
    upper = height_at_angle(distance, np.deg2rad(c.max_elev), antenna, c.k)
    lower = np.maximum(lower, terrain)
    lower[~known | (lower > upper)] = np.nan
    target = np.full_like(terrain, c.target_m) if c.reference == 'AMSL' else terrain + c.target_m
    visible = known & (target >= lower - 1e-6) & (target <= upper + 1e-6)
    if c.csc_enabled:
        if antenna_pattern is not None:
            visible &= pattern_allows(distance[None, :], target, antenna, c, antenna_pattern)
        else:
            visible &= csc_allows(distance[None, :], target, antenna, c)
    status = np.where(known, visible.astype(float), np.nan)
    return dict(az=az, distance=distance, terrain=terrain, lower=lower,
                upper=np.broadcast_to(upper, terrain.shape).copy(), status=status,
                target=target, antenna=antenna, site_height=site_height,
                config=c, horizon=horizon, known=known, antenna_pattern=antenna_pattern)

def demo_terrain(c):
    az, distance = axes(c)
    x = np.sin(np.deg2rad(az))[:, None] * distance[None, :]
    y = np.cos(np.deg2rad(az))[:, None] * distance[None, :]
    def surface(x, y):
        return 200 + 650 * np.exp(-((x - 16000) / 4500)**2 - ((y - 5000) / 17000)**2) + 300 * np.exp(-((x + 24000) / 14000)**2 - ((y - 30000) / 6000)**2)
    return surface(x, y), float(surface(0, 0))


# ========================================================================
# 2. OPENTOPOGRAPHY, TERÉN A EXPORT
# ========================================================================

import hashlib
import json
import math
import os
from pathlib import Path
import tempfile
import urllib.request
import urllib.parse
import urllib.error
import numpy as np

DATASETS = ('COP30', 'COP90', 'SRTMGL1', 'SRTMGL3', 'NASADEM')
ENDPOINT = 'https://portal.opentopography.org/API/globaldem'

def bounding_box(c):
    from pyproj import Geod
    az = np.linspace(0, 360, 1441)
    lon, lat, _ = Geod(ellps='WGS84').fwd(np.full_like(az, c.lon), np.full_like(az, c.lat), az,
                                         np.full_like(az, c.range_km * 1000 + 1000))
    if np.ptp(lon) > 180:
        raise ValueError('Výřez přes datovou hranici zatím není podporován.')
    return dict(south=float(min(lat)), north=float(max(lat)), west=float(min(lon)), east=float(max(lon)))

def _opentopo_error_message(payload, content_type=''):
    """Vrátí bezpečný stručný popis textové/JSON odpovědi OpenTopography."""
    if not payload:
        return ''
    sample = payload[:65536]
    text = sample.decode('utf-8', errors='replace').strip()

    # HTML -> plain text
    if '<' in text and '>' in text:
        import re
        text = re.sub(r'(?is)<script.*?</script>|<style.*?</style>', ' ', text)
        text = re.sub(r'(?s)<[^>]+>', ' ', text)
        text = re.sub(r'\s+', ' ', text).strip()

    # JSON -> prefer common error/message fields.
    if text.startswith(('{', '[')):
        try:
            obj = json.loads(text)
            if isinstance(obj, dict):
                for field in ('error', 'message', 'detail', 'description', 'status'):
                    value = obj.get(field)
                    if value:
                        if isinstance(value, (dict, list)):
                            value = json.dumps(value, ensure_ascii=False)
                        text = str(value)
                        break
        except Exception:
            pass

    text = ' '.join(text.split())
    if len(text) > 500:
        text = text[:497] + '...'
    return text

def download(c, key, dataset, progress=lambda *args: None, bbox=None, force=False):
    import rasterio
    if dataset not in DATASETS:
        raise ValueError('Neznámý dataset.')
    if not key.strip():
        raise ValueError('Zadej API klíč OpenTopography.')
    box = bbox or bounding_box(c)
    area = ((box['north'] - box['south']) * 111.32 * (box['east'] - box['west']) * 111.32
            * math.cos(math.radians((box['north'] + box['south']) / 2)))
    limit = 4_050_000 if dataset in ('COP90', 'SRTMGL3') else 450_000
    if area > limit * 0.98:
        raise ValueError('Výřez překračuje limit API. Zmenši dosah nebo zvol 90m model.')
    params = dict(demtype=dataset, **box, outputFormat='GTiff')
    digest = hashlib.sha256(json.dumps(params, sort_keys=True).encode()).hexdigest()[:24]
    cache = Path(os.environ.get('LOCALAPPDATA', str(Path.home() / '.cache'))) / 'RadarCoverage' / 'dem'
    cache.mkdir(parents=True, exist_ok=True)
    dest = cache / (dataset + '_' + digest + '.tif')
    if dest.exists() and not force:
        progress('Používám uložený výřez terénu.')
        return dest
    url = ENDPOINT + '?' + urllib.parse.urlencode(dict(params, API_Key=key.strip()))
    fd, tmp = tempfile.mkstemp(suffix='.tif', dir=cache)
    os.close(fd)
    try:
        progress('Stahuji terén z OpenTopography…')
        # Refuse redirects: do not forward a credential to another location.
        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, req, fp, code, msg, headers, newurl):
                return None
        opener = urllib.request.build_opener(NoRedirect())
        req = urllib.request.Request(url, headers={'User-Agent': 'RadarCoveragePrototype/0.1'})
        content_type = ''
        response_prefix = bytearray()
        with opener.open(req, timeout=180) as response, open(tmp, 'wb') as out:
            content_type = (response.headers.get('Content-Type') or '').lower()
            total = 0
            while True:
                chunk = response.read(1024 * 1024)
                if not chunk:
                    break
                if len(response_prefix) < 65536:
                    response_prefix.extend(chunk[:65536 - len(response_prefix)])
                total += len(chunk)
                if total > 2_000_000_000:
                    raise ValueError('Výřez přesahuje bezpečnostní limit 2 GB.')
                out.write(chunk)
                progress(f'Stahuji terén: {total / 1048576:.1f} MB')

        # TIFF / BigTIFF magic bytes. Když server vrátí JSON/HTML s HTTP 200,
        # zobrazíme skutečnou zprávu namísto obecného "neplatný rastr".
        prefix = bytes(response_prefix)
        tiff_magic = (
            prefix.startswith(b'II*\x00') or prefix.startswith(b'MM\x00*') or
            prefix.startswith(b'II+\x00') or prefix.startswith(b'MM\x00+')
        )
        textual_type = any(token in content_type for token in
                           ('text/', 'json', 'xml', 'html', 'javascript'))

        if not tiff_magic and (textual_type or prefix[:1] in (b'{', b'[', b'<')):
            detail = _opentopo_error_message(prefix, content_type)
            if detail:
                raise ValueError(
                    'OpenTopography místo GeoTIFFu vrátilo zprávu serveru:\n\n'
                    + detail
                )
            raise ValueError(
                f'OpenTopography místo GeoTIFFu vrátilo typ {content_type or "neznámý obsah"}.'
            )

        try:
            with rasterio.open(tmp) as ds:
                if not ds.crs:
                    raise ValueError('rastr nemá CRS')
                if ds.count < 1:
                    raise ValueError('rastr nemá datové pásmo')
                if ds.width < 1 or ds.height < 1:
                    raise ValueError('rastr má nulový rozměr')
        except Exception as exc:
            detail = _opentopo_error_message(prefix, content_type)
            suffix = f' Server: {detail}' if detail else ''
            raise ValueError(
                'OpenTopography stáhlo soubor, ale Rasterio jej neumí otevřít jako '
                f'platný georeferencovaný GeoTIFF ({exc}).'
                + suffix
            ) from None
        os.replace(tmp, dest)
        return dest
    except urllib.error.HTTPError as exc:
        msg = {401: 'Klíč nebyl přijat.',
               403: 'Přístup k datasetu není povolen.',
               404: 'API endpoint nebo požadovaný zdroj nebyl nalezen.',
               413: 'Požadovaná oblast je příliš velká.',
               429: 'Vyčerpán denní limit API požadavků.'}.get(
                   exc.code, 'Požadavek selhal; zkontroluj oblast, dataset a účet.')
        try:
            server_detail = _opentopo_error_message(exc.read(65536),
                                                    exc.headers.get('Content-Type', '') if exc.headers else '')
        except Exception:
            server_detail = ''
        if server_detail:
            msg += '\n\nServer: ' + server_detail
        raise ValueError(f'OpenTopography HTTP {exc.code}: {msg}') from None
    except (urllib.error.URLError, TimeoutError, OSError):
        raise ValueError('Stažení selhalo: síť, časový limit nebo zápis na disk. Klíč nebyl zalogován.') from None
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)

def sample(path, c, progress=lambda *args: None):
    """Sample the DEM at all polar grid points with vectorized coordinates.

    The old implementation called ``Dataset.sample`` point-by-point for every
    radial.  Here geodesic and CRS transforms are vectorized once.  Modest
    rasters are read once; large rasters are accessed by native GDAL blocks so
    we do not have to load a multi-gigabyte DEM into RAM.
    """
    import rasterio
    from rasterio.windows import Window
    from pyproj import Geod, Transformer

    az, distance = axes(c)
    geod = Geod(ellps='WGS84')
    point_count = len(az) * len(distance)
    progress(f'Připravuji {point_count:,} vzorků terénu…'.replace(',', ' '), 0, point_count)

    with rasterio.open(path) as ds:
        if ds.crs is None:
            raise ValueError('Rastr nemá souřadnicový systém.')

        transformer = Transformer.from_crs('EPSG:4326', ds.crs, always_xy=True)
        scale = float(ds.scales[0]) if ds.scales else 1.0
        offset = float(ds.offsets[0]) if ds.offsets else 0.0

        # Site height: one explicit nearest-pixel read, independent of the
        # coverage grid (whose first radial sample starts away from the site).
        site_x, site_y = transformer.transform(c.lon, c.lat)
        inv = ~ds.transform
        site_col_f = inv.a * site_x + inv.b * site_y + inv.c
        site_row_f = inv.d * site_x + inv.e * site_y + inv.f
        site_col, site_row = int(np.floor(site_col_f)), int(np.floor(site_row_f))
        if not (0 <= site_row < ds.height and 0 <= site_col < ds.width):
            raise ValueError('Stanoviště radaru leží mimo platná data DEM.')
        site_value = ds.read(1, window=Window(site_col, site_row, 1, 1), masked=True)[0, 0]
        if np.ma.is_masked(site_value):
            raise ValueError('Stanoviště radaru leží mimo platná data DEM.')
        ground = float(site_value) * scale + offset
        if not np.isfinite(ground):
            raise ValueError('Stanoviště radaru leží mimo platná data DEM.')

        # One vectorized geodesic call and one CRS transform for the whole
        # polar grid. The application already limits this grid to 2 M points.
        az_flat = np.repeat(az, len(distance))
        distance_flat = np.tile(distance, len(az))
        lon, lat, _ = geod.fwd(
            np.full(point_count, c.lon, dtype=float),
            np.full(point_count, c.lat, dtype=float),
            az_flat, distance_flat)
        progress('Převádím vzorky do souřadnic DEM…', point_count // 5, point_count)
        x, y = transformer.transform(lon, lat)
        del lon, lat, az_flat, distance_flat

        col_f = inv.a * x + inv.b * y + inv.c
        row_f = inv.d * x + inv.e * y + inv.f
        del x, y
        cols = np.floor(col_f).astype(np.int64)
        rows = np.floor(row_f).astype(np.int64)
        del col_f, row_f

        inside = ((rows >= 0) & (rows < ds.height) &
                  (cols >= 0) & (cols < ds.width))
        output_flat = np.full(point_count, np.nan, dtype=float)
        inside_indices = np.flatnonzero(inside)
        if inside_indices.size:
            valid_rows = rows[inside_indices]
            valid_cols = cols[inside_indices]

            # Reading a complete modest raster is fastest. For large datasets,
            # group requested pixels by the raster's native block layout and
            # read every touched block at most once.
            dtype_size = np.dtype(ds.dtypes[0]).itemsize
            raw_band_bytes = ds.width * ds.height * dtype_size
            full_read_limit = 256 * 1024 * 1024

            if raw_band_bytes <= full_read_limit:
                progress('Načítám DEM do paměti pro rychlé vzorkování…',
                         point_count // 3, point_count)
                band = ds.read(1, masked=True)
                selected = band[valid_rows, valid_cols]
                values = np.ma.filled(selected, np.nan).astype(float, copy=False)
                output_flat[inside_indices] = values * scale + offset
            else:
                block_h, block_w = ds.block_shapes[0]
                block_cols = int(np.ceil(ds.width / block_w))
                block_ids = (valid_rows // block_h) * block_cols + (valid_cols // block_w)
                order = np.argsort(block_ids, kind='stable')
                sorted_ids = block_ids[order]
                boundaries = np.r_[0, np.flatnonzero(np.diff(sorted_ids)) + 1, len(order)]
                groups = len(boundaries) - 1
                report_every = max(1, groups // 100)

                for group_index, (a, b) in enumerate(zip(boundaries[:-1], boundaries[1:])):
                    group_order = order[a:b]
                    first = group_order[0]
                    block_row = valid_rows[first] // block_h
                    block_col = valid_cols[first] // block_w
                    row0 = int(block_row * block_h)
                    col0 = int(block_col * block_w)
                    height = min(block_h, ds.height - row0)
                    width = min(block_w, ds.width - col0)
                    block = ds.read(1, window=Window(col0, row0, width, height), masked=True)
                    rr = valid_rows[group_order] - row0
                    cc = valid_cols[group_order] - col0
                    selected = block[rr, cc]
                    values = np.ma.filled(selected, np.nan).astype(float, copy=False)
                    output_flat[inside_indices[group_order]] = values * scale + offset

                    if group_index % report_every == 0 or group_index + 1 == groups:
                        completed = int(point_count * (0.35 + 0.65 * (group_index + 1) / groups))
                        progress(f'Vzorkuji DEM bloky: {group_index + 1}/{groups}',
                                 min(completed, point_count), point_count)

        progress('Vzorkování terénu dokončeno.', point_count, point_count)
        return output_flat.reshape(len(az), len(distance)), ground

def export_tiff(path, result, levels_ft=()):
    import rasterio
    from rasterio.transform import from_origin
    from pyproj import CRS
    c = result['config']
    radius = c.range_km * 1000
    # Export is a nearest polar sample visualization, not a new terrain calculation.
    side = min(1600, int(np.ceil(2 * radius / c.step_m)))
    pixel = 2 * radius / side
    axis = -radius + (np.arange(side) + 0.5) * pixel
    x, y = np.meshgrid(axis, -axis)
    r = np.hypot(x, y)
    az = np.rad2deg(np.arctan2(x, y)) % 360
    ai, in_sector = azimuth_indices(result['az'], c, az)
    dr = result['distance'][0]
    ri = np.clip(np.rint(r / dr).astype(int) - 1, 0, len(result['distance']) - 1)
    outside = (r > radius) | (r < dr / 2) | ~in_sector
    crs = CRS.from_proj4(f'+proj=aeqd +lat_0={c.lat} +lon_0={c.lon} +datum=WGS84 +units=m')
    with rasterio.open(path, 'w', driver='GTiff', width=side, height=side, count=2 + len(levels_ft),
                       dtype='float32', crs=crs, transform=from_origin(-radius, radius, pixel, pixel),
                       nodata=-9999, compress='deflate') as ds:
        for band, name in enumerate(('status', 'lower'), 1):
            data = result[name][ai, ri].astype('float32')
            data[outside | ~np.isfinite(data)] = -9999
            ds.write(data, band)
        ds.set_band_description(1, 'Geometric visibility: 1 visible, 0 blocked, nodata unknown')
        ds.set_band_description(2, 'Minimum geometric coverage height AMSL m; nodata unknown or empty interval')
        for band, ft in enumerate(levels_ft, 3):
            data = status_at_height(result, ft * FT_TO_M)[ai, ri].astype('float32')
            data[outside | ~np.isfinite(data)] = -9999
            ds.write(data, band)
            ds.set_band_description(band, f'{ft} ft nominal ISA AMSL: 1 visible, 0 blocked, nodata unknown')
        from dataclasses import asdict
        pattern = result.get('antenna_pattern')
        ds.update_tags(model='effective_spherical_earth', version='0.9', config=json.dumps(asdict(c)),
                       levels_ft=json.dumps(list(levels_ft)), beam_mode=c.beam_mode, flight_level_assumption='nominal ISA height, no weather correction',
                       antenna_pattern=pattern.name if pattern is not None else 'built-in analytical cosecant-squared',
                       source=result.get('source', 'unknown'), interpolation='nearest polar sample',
                       vertical_reference='source DEM orthometric datum, no geoid conversion',
                       caution='Prototype, geometric visibility only; no detection probability')


def export_gpkg_raster(path, result, levels_ft=None, progress=lambda *args: None):
    """Export every computed map and height preset as an independent QGIS raster.

    Uses GDAL's GeoPackage gridded coverage extension (lossless Float32 TIFF).
    Writes to a sibling temporary file, replacing the destination only on success.
    OSM background tiles are not calculated coverage layers and are not included.
    """
    import rasterio
    from rasterio.transform import from_origin
    from pyproj import CRS
    levels = tuple(dict.fromkeys(FLIGHT_LEVELS_LIST if levels_ft is None else levels_ft))
    if any(not np.isfinite(ft) or ft < 0 for ft in levels):
        raise ValueError('Neplatná výška exportované vrstvy.')
    c = result['config']
    radius = c.range_km * 1000
    side = min(1600, int(np.ceil(2 * radius / c.step_m)))
    pixel = 2 * radius / side
    axis = -radius + (np.arange(side) + 0.5) * pixel
    x, y = np.meshgrid(axis, -axis)
    r = np.hypot(x, y)
    az = np.rad2deg(np.arctan2(x, y)) % 360
    ai, in_sector = azimuth_indices(result['az'], c, az)
    dr = result['distance'][0]
    ri = np.clip(np.rint(r / dr).astype(int) - 1, 0, len(result['distance']) - 1)
    outside = (r > radius) | (r < dr / 2) | ~in_sector
    crs = CRS.from_user_input(local_crs(c))
    specs = [
        ('target_coverage', 'Kryti vlastniho cile', 'status', '1 visible; 0 blocked; NoData unknown'),
        ('terrain_amsl_m', 'Teren [m AMSL]', 'terrain', 'Sampled source DEM, metres AMSL'),
        ('lower_coverage_amsl_m', 'Spodni hranice kryti [m AMSL]', 'lower', 'Minimum geometric height; NoData unknown or empty interval'),
        ('upper_envelope_amsl_m', 'Horni geometricka obalka [m AMSL]', 'upper', 'Geometric upper bound; antenna pattern may further restrict visibility'),
        ('known_terrain_profile', 'Platnost terenniho profilu', 'known', '1 known; 0 unknown terrain profile'),
        ('target_height_amsl_m', 'Vyska vlastniho cile [m AMSL]', 'target', 'Target height converted to AMSL'),
        ('terrain_horizon_deg', 'Terenni horizont [deg]', 'horizon', 'Maximum apparent terrain elevation angle in degrees'),
    ]
    specs += [(f'coverage_{str(ft).replace(".", "_")}_ft', level_label(ft), ft,
               '1 visible; 0 blocked; NoData unknown; nominal ISA AMSL') for ft in levels]
    path = Path(path)
    pattern = result.get('antenna_pattern')
    with tempfile.TemporaryDirectory(prefix='.radar_qgis_', dir=path.parent) as tmp:
        staging = Path(tmp) / 'coverage.gpkg'
        with rasterio.Env() as env:
            if 'GPKG' not in env.drivers():
                raise ValueError('Instalace rasterio/GDAL nepodporuje GeoPackage (GPKG).')
        for index, (table, title, key, description) in enumerate(specs):
            progress(f'Exportuji QGIS: {title}', index + 1, len(specs))
            polar = result[key] if isinstance(key, str) else status_at_height(result, key * FT_TO_M)
            if key == 'horizon':
                polar = np.where(result['known'], np.rad2deg(polar), np.nan)
            if key == 'upper':
                polar = np.where(result['known'] & np.isfinite(result['lower']), polar, np.nan)
            data = polar[ai, ri].astype('float32')
            data[outside | ~np.isfinite(data)] = -9999
            with rasterio.open(staging, 'w', driver='GPKG', width=side, height=side,
                               count=1, dtype='float32', crs=crs,
                               transform=from_origin(-radius, radius, pixel, pixel),
                               nodata=-9999, TILE_FORMAT='TIFF', RASTER_TABLE=table,
                               RASTER_IDENTIFIER=title, RASTER_DESCRIPTION=description,
                               APPEND_SUBDATASET='YES' if index else 'NO') as ds:
                ds.write(data, 1)
                ds.set_band_description(1, title)
                ds.update_tags(config=json.dumps(asdict(c)), levels_ft=json.dumps(levels),
                               source=result.get('source', 'unknown'), beam_mode=c.beam_mode,
                               antenna_pattern=pattern.name if pattern is not None else 'built-in analytical cosecant-squared',
                               interpolation='nearest polar sample', pixel_size_m=str(pixel),
                               vertical_reference='source DEM orthometric datum, no geoid conversion',
                               model='effective_spherical_earth', description=description)
        # Rasterio/GDAL builds may ignore creation-time nodata for GPKG.
        # Store the sentinel in the standard gridded-coverage metadata.
        import sqlite3
        from contextlib import closing
        with closing(sqlite3.connect(staging)) as db, db:
            db.execute('UPDATE gpkg_2d_gridded_coverage_ancillary SET data_null = ?', (-9999,))
        # Check all tables before replacing an existing export.
        with rasterio.open(staging) as ds:
            if len(ds.subdatasets) != len(specs):
                raise ValueError('Kontrola GeoPackage selhala: chybi exportovane vrstvy.')
        os.replace(staging, path)
    return len(specs)


def calculation_metadata(result):
    c = result['config']
    pattern = result.get('antenna_pattern')
    return dict(config=asdict(c), source=result.get('source', 'unknown'),
        completed_at=result.get('completed_at'), duration_s=result.get('duration_s'),
        shape=list(result['terrain'].shape), samples=int(result['terrain'].size),
        known_samples=int(np.count_nonzero(result['known'])),
        radar_ground_amsl_m=float(result['site_height']), antenna_amsl_m=float(result['antenna']),
        crs=local_crs(c), vertical_reference='source DEM datum; no geoid conversion',
        actual_azimuth_step_deg=actual_azimuth_step(result),
        radial_step_m=float(result['distance'][0]),
        antenna_pattern=pattern.name if pattern is not None else 'built-in csc2',
        beam_mode=c.beam_mode,
        scan_model=('ideal azimuth sweep, boresight vertical cut; no elevation scan or steering loss'
                    if c.radar_mode == 'PAR-NG' else 'full azimuth coverage'),
        azimuth_axis='continuous degrees; modulo 360 gives compass bearing',
        scan_limits_deg=([float(result['az'][0]), float(result['az'][-1])]
                         if c.radar_mode == 'PAR-NG' else [0,360]),
        pattern_sha256=(pattern.source_sha256 if isinstance(pattern, ParScanPattern) else None),
        source_peak_db=(pattern.source_peak_db if isinstance(pattern, ParScanPattern) else None),
        gain_normalization='relative to global pattern maximum',
        antenna_channels=('LOW Tx/Rx + HIGH Rx-only' if isinstance(pattern, AntennaPatternPair)
                          else 'single beam'),
        low_peak_dbi=(pattern.low_peak_dbi if isinstance(pattern, AntennaPatternPair) else None),
        high_peak_dbi=(pattern.high_peak_dbi if isinstance(pattern, AntennaPatternPair) else None),
        ssr_model=(dict(range_limit_nm=256, range_limit_type='slant range',
            assumptions=dict(SSR_ASSUMPTIONS),
            method='min(Friis uplink, Friis downlink, 256 NM); effective Earth geometry and terrain LOS',
            limitations='illustrative Gaussian antenna; no measured pattern, multipath, diffraction, interference, garbling, SLS or Pd/Pfa')
            if c.radar_mode == 'SSR' else None),
        model='effective spherical Earth; geometric visibility and antenna envelope, not Pd/Pfa',
        vector_method='0.5 contour in native polar sampling grid; no raster resampling or cosmetic smoothing')


def coverage_polygons(result, status):
    """Native polar contour polygons, with holes, repaired and joined at north seam."""
    import contourpy
    try:
        from shapely.geometry import Polygon
        from shapely.ops import unary_union
    except ImportError:
        raise ValueError('Pro vektorový export nainstaluj: python -m pip install shapely') from None
    az, distance = result['az'], result['distance']
    periodic = result['config'].radar_mode != 'PAR-NG'
    angles = np.deg2rad(np.r_[az, 360] if periodic else az)
    radii = np.r_[distance[0]/2, distance]
    x = np.sin(angles)[:, None] * radii
    y = np.cos(angles)[:, None] * radii
    if periodic:
        x[-1], y[-1] = x[0], y[0]  # exact periodic seam
    z = np.where(np.isfinite(status), status, 0.0)
    z = np.column_stack([z[:, :1], z])
    if periodic:
        z = np.vstack([z, z[:1]])
    if not np.any(z == 1):
        return []
    points, offsets = contourpy.contour_generator(x=x, y=y, z=z,
        fill_type='OuterOffset', corner_mask=False).filled(0.5, 1.5)
    polygons = []
    def collect(geom):
        if geom.is_empty:
            return
        if geom.geom_type == 'Polygon':
            if geom.area > 1e-6:
                polygons.append(geom)
        elif hasattr(geom, 'geoms'):
            for part in geom.geoms:
                collect(part)
    for vertices, starts in zip(points, offsets):
        rings = [vertices[a:b] for a, b in zip(starts[:-1], starts[1:])]
        poly = Polygon(rings[0], rings[1:])
        collect(poly if poly.is_valid else poly.buffer(0))
    merged = unary_union(polygons)
    polygons = []
    collect(merged)
    return polygons


def export_gpkg(path, result, levels_ft=None, progress=lambda *args: None):
    """Standard OGC GeoPackage vector features, no pixel-size cap."""
    import sqlite3, struct
    from pyproj import CRS
    try:
        from shapely.geometry import MultiLineString
    except ImportError:
        raise ValueError('Pro vektorový export nainstaluj: python -m pip install shapely') from None
    levels = tuple(dict.fromkeys(FLIGHT_LEVELS_LIST if levels_ft is None else levels_ft))
    if any(not isinstance(ft, (int, float)) or not np.isfinite(ft) or ft < 0 for ft in levels):
        raise ValueError('Neplatné výšky pro export.')
    # Evaluate one height at a time to keep peak memory bounded.
    path = Path(path)
    with tempfile.TemporaryDirectory(prefix='.radar_vectors_', dir=path.parent) as tmp:
        staging = Path(tmp)/'coverage.gpkg'
        from contextlib import closing
        with closing(sqlite3.connect(staging)) as db, db:
            db.executescript("""
                PRAGMA application_id=1196444487; PRAGMA user_version=10300;
                CREATE TABLE gpkg_spatial_ref_sys (srs_name TEXT NOT NULL,srs_id INTEGER NOT NULL PRIMARY KEY,
                    organization TEXT NOT NULL,organization_coordsys_id INTEGER NOT NULL,definition TEXT NOT NULL,description TEXT);
                CREATE TABLE gpkg_contents (table_name TEXT NOT NULL PRIMARY KEY,data_type TEXT NOT NULL,
                    identifier TEXT UNIQUE,description TEXT DEFAULT '',last_change DATETIME NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
                    min_x DOUBLE,min_y DOUBLE,max_x DOUBLE,max_y DOUBLE,srs_id INTEGER);
                CREATE TABLE gpkg_geometry_columns (table_name TEXT NOT NULL,column_name TEXT NOT NULL,
                    geometry_type_name TEXT NOT NULL,srs_id INTEGER NOT NULL,z TINYINT NOT NULL,m TINYINT NOT NULL,
                    PRIMARY KEY(table_name,column_name));
            """)
            for row in [('Undefined Cartesian',-1,'NONE',-1,'undefined',''),
                        ('Undefined Geographic',0,'NONE',0,'undefined',''),
                        ('WGS84',4326,'EPSG',4326,CRS.from_epsg(4326).to_wkt('WKT1_GDAL'),''),
                        ('Radar AEQD',100000,'NONE',100000,CRS.from_user_input(local_crs(result['config'])).to_wkt('WKT1_GDAL'),'metres')]:
                db.execute('INSERT INTO gpkg_spatial_ref_sys VALUES (?,?,?,?,?,?)',row)
            db.execute('CREATE TABLE calculation (id INTEGER PRIMARY KEY, metadata_json TEXT NOT NULL)')
            db.execute("INSERT INTO gpkg_contents(table_name,data_type,identifier,description) VALUES ('calculation','attributes','calculation','Calculation provenance')")
            db.execute('INSERT INTO calculation VALUES (1,?)',(json.dumps(calculation_metadata(result),ensure_ascii=False),))
            count = 0
            for index, ft in enumerate((None,)+levels):
                name = 'target' if ft is None else 'height_'+str(ft).replace('.','_')+'_ft'
                status = result['status'] if ft is None else status_at_height(result, ft*FT_TO_M)
                polygons = coverage_polygons(result,status)
                for suffix, geom_type in [('areas','POLYGON'),('boundaries','MULTILINESTRING')]:
                    table = name+'_'+suffix
                    db.execute(f'CREATE TABLE "{table}" (fid INTEGER PRIMARY KEY AUTOINCREMENT,geom BLOB NOT NULL,height_ft REAL,reference TEXT,area_km2 REAL)')
                    db.execute('INSERT INTO gpkg_contents(table_name,data_type,identifier,description,srs_id) VALUES (?,?,?,?,?)',
                        (table,'features',table,'Native polar contour; no smoothing; unknown areas excluded',100000))
                    db.execute('INSERT INTO gpkg_geometry_columns VALUES (?,?,?,?,0,0)',(table,'geom',geom_type,100000))
                    bounds=[]
                    for poly in polygons:
                        geom=poly if suffix=='areas' else MultiLineString([poly.exterior.coords]+[ring.coords for ring in poly.interiors])
                        header=b'GP'+bytes([0,1])+struct.pack('<i',100000)
                        db.execute(f'INSERT INTO "{table}"(geom,height_ft,reference,area_km2) VALUES (?,?,?,?)',
                            (header+geom.wkb,ft, 'AMSL' if ft is not None else result['config'].reference,poly.area/1e6))
                        bounds.append(poly.bounds)
                    if bounds:
                        b=np.asarray(bounds)
                        db.execute('UPDATE gpkg_contents SET min_x=?,min_y=?,max_x=?,max_y=? WHERE table_name=?',
                            (float(b[:,0].min()),float(b[:,1].min()),float(b[:,2].max()),float(b[:,3].max()),table))
                    count+=1
                progress(f'Vektory: {name}',index+1,len(levels)+1)
            if db.execute('PRAGMA integrity_check').fetchone()[0]!='ok':
                raise ValueError('Kontrola vektorového GeoPackage selhala.')
        os.replace(staging,path)
    return count


def export_raw_npz(path, result):
    arrays={key:result[key] for key in ('az','distance','terrain','lower','upper','status','target','horizon','known')}
    pattern=result.get('antenna_pattern')
    if pattern is not None:
        arrays.update({f'pattern_{k}':v for k,v in vars(pattern).items() if isinstance(v,np.ndarray)})
    with open(path,'wb') as stream:
        np.savez_compressed(stream,**arrays,metadata_json=json.dumps(calculation_metadata(result),ensure_ascii=False))


def export_profile_csv(path,result,index,levels_ft=()):
    import csv
    with open(path,'w',newline='',encoding='utf-8-sig') as stream:
        writer=csv.writer(stream)
        writer.writerow(['azimuth_deg','distance_m','terrain_amsl_m','lower_amsl_m','upper_amsl_m',
                         'target_amsl_m','horizon_deg','known','target_visible']+[f'visible_{ft}_ft_AMSL' for ft in levels_ft])
        cell=dict(result)
        for key in ('terrain','lower','upper','known'):
            cell[key]=result[key][index:index+1]
        layers=[status_at_height(cell,ft*FT_TO_M)[0] for ft in levels_ft]
        for j,d in enumerate(result['distance']):
            row=[result['az'][index],d]+[result[k][index,j] for k in ('terrain','lower','upper','target')]
            row += [np.rad2deg(result['horizon'][index,j]),int(result['known'][index,j]),result['status'][index,j]]
            writer.writerow(row+[layer[j] for layer in layers])


def local_crs(c):
    return f'+proj=aeqd +lat_0={c.lat} +lon_0={c.lon} +datum=WGS84 +units=m'

BASEMAP_PROVIDERS = {
    'OpenStreetMap': {
        'cache': 'osm', 'url': 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
        'max_zoom': 18, 'attribution': '© OpenStreetMap contributors',
    },
    'OpenTopoMap': {
        'cache': 'opentopomap', 'url': 'https://tile.opentopomap.org/{z}/{x}/{y}.png',
        'max_zoom': 17,
        'attribution': '© OpenStreetMap contributors · SRTM / Sonny\n© OpenTopoMap (CC-BY-SA)',
    },
}
BASEMAP_PROVIDERS['Satelitní · Esri'] = {
    'cache': 'esri_world_imagery',
    'url': 'https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    'max_zoom': 19,
    'attribution': 'Source: Esri, Vantor, Earthstar Geographics, and the GIS User Community',
}
BASEMAP_OPTIONS = (*BASEMAP_PROVIDERS, 'Bez podkladu')
# Provider documentation: https://opentopomap.org/about

def basemap_attribution(layer):
    return layer.get('attribution', BASEMAP_PROVIDERS['OpenStreetMap']['attribution'])

def tile_plan(c, viewport=None, pixel_width=1000, max_zoom=18):
    """Choose only OSM tiles currently visible in the requested AEQD viewport."""
    from pyproj import Transformer
    if viewport is None:
        xmin, xmax, ymin, ymax = -c.range_km, c.range_km, -c.range_km, c.range_km
    else:
        xmin, xmax, ymin, ymax = map(float, viewport)
        if not (xmin < xmax and ymin < ymax):
            raise ValueError('Neplatný výřez mapy.')
    edge_x = np.linspace(xmin * 1000, xmax * 1000, 101)
    edge_y = np.linspace(ymin * 1000, ymax * 1000, 101)
    x = np.r_[edge_x, edge_x, np.full(101, xmin * 1000), np.full(101, xmax * 1000)]
    y = np.r_[np.full(101, ymin * 1000), np.full(101, ymax * 1000), edge_y, edge_y]
    lon, lat = Transformer.from_crs(local_crs(c), 'EPSG:4326', always_xy=True).transform(x, y)
    if np.ptp(lon) > 180 or np.max(np.abs(lat)) > 85.0:
        raise ValueError('Podklad není dostupný přes datovou hranici nebo za 85° šířky.')
    # Around 1000 horizontal pixels at the latitude of the radar, bounded requests.
    visible_width_m = max(1.0, (xmax - xmin) * 1000)
    pixel_width = max(256, int(pixel_width))
    zoom = int(np.clip(np.floor(np.log2(156543.0339 * np.cos(np.deg2rad(c.lat)) /
                                       (visible_width_m / pixel_width))), 1, max_zoom))
    while True:
        n = 2**zoom
        xx = (np.asarray(lon) + 180) / 360 * n
        yy = (1 - np.arcsinh(np.tan(np.deg2rad(lat))) / np.pi) / 2 * n
        xmin, xmax = np.clip(np.floor([xx.min(), xx.max()]).astype(int), 0, n - 1)
        ymin, ymax = np.clip(np.floor([yy.min(), yy.max()]).astype(int), 0, n - 1)
        if (xmax-xmin+1)*(ymax-ymin+1) <= 36 or zoom == 1:
            return zoom, int(xmin), int(xmax), int(ymin), int(ymax)
        zoom -= 1

def fetch_osm_tile(z, x, y):
    return fetch_map_tile(z, x, y, 'OpenStreetMap')

def fetch_map_tile(z, x, y, provider):
    import time
    import io
    from PIL import Image
    spec = BASEMAP_PROVIDERS[provider]
    cache = Path(os.environ.get('LOCALAPPDATA', str(Path.home() / '.cache'))) / 'RadarCoverage' / spec['cache']
    cache.mkdir(parents=True, exist_ok=True)
    path = cache / f'{z}_{x}_{y}.png'
    metadata = cache / f'{z}_{x}_{y}.json'
    headers = {}
    if path.exists():
        try:
            if time.time() - path.stat().st_mtime < 7 * 86400:
                with Image.open(path) as image:
                    return np.array(image.convert('RGBA'))
            headers = json.loads(metadata.read_text()) if metadata.exists() else {}
        except (OSError, ValueError):
            headers = {}
    req_headers = {'User-Agent': 'ELDIS-RadarCoverage/0.8'}
    if headers.get('etag'):
        req_headers['If-None-Match'] = headers['etag']
    if headers.get('modified'):
        req_headers['If-Modified-Since'] = headers['modified']
    request = urllib.request.Request(spec['url'].format(z=z, x=x, y=y), headers=req_headers)
    for attempt in range(3):
        try:
            with urllib.request.urlopen(request, timeout=15) as response:
                data = response.read(2_000_001)
                if len(data) > 2_000_000:
                    raise ValueError('Neplatná mapová dlaždice.')
                with Image.open(io.BytesIO(data)) as image:
                    if image.size != (256, 256):
                        raise ValueError('Neplatný rozměr mapové dlaždice.')
                    pixels = np.array(image.convert('RGBA'))
                fd, temp_path = tempfile.mkstemp(suffix='.png', dir=cache)
                try:
                    with os.fdopen(fd, 'wb') as stream:
                        stream.write(data)
                    os.replace(temp_path, path)
                finally:
                    if os.path.exists(temp_path):
                        os.unlink(temp_path)
                metadata.write_text(json.dumps({'etag': response.headers.get('ETag'),
                                                'modified': response.headers.get('Last-Modified')}))
                return pixels
        except urllib.error.HTTPError as exc:
            if exc.code == 304 and path.exists():
                os.utime(path, None)
                with Image.open(path) as image:
                    return np.array(image.convert('RGBA'))
            if exc.code == 429 and attempt < 2:
                # Respect Retry-After when it is a small numeric delay; otherwise
                # use a conservative exponential backoff. Tile requests stay serial.
                try:
                    retry_after = float(exc.headers.get('Retry-After', '')) if exc.headers else 0.0
                except ValueError:
                    retry_after = 0.0
                delay = min(10.0, max(1.0, retry_after or 2.0**attempt))
                time.sleep(delay)
                continue
            raise ValueError(f'{provider} HTTP {exc.code}; mapa není dostupná.') from None
        except (urllib.error.URLError, TimeoutError, OSError):
            raise ValueError('Mapový podklad se nepodařilo načíst. Zkontroluj internet.') from None

def load_basemap(c, progress=lambda *args: None, viewport=None, out_size=(1000, 1000),
                 provider='OpenStreetMap'):
    """Fetch the current viewport and reproject Web Mercator tiles into radar AEQD."""
    from rasterio.warp import reproject, Resampling
    from rasterio.transform import from_bounds
    width = int(np.clip(out_size[0], 256, 1600))
    height = int(np.clip(out_size[1], 256, 1600))
    spec = BASEMAP_PROVIDERS[provider]
    z, xmin, xmax, ymin, ymax = tile_plan(c, viewport, width, spec['max_zoom'])
    mosaic = np.zeros(((ymax-ymin+1)*256, (xmax-xmin+1)*256, 4), dtype='uint8')
    total = (xmax-xmin+1)*(ymax-ymin+1)
    done = 0
    for y in range(ymin, ymax+1):
        for x in range(xmin, xmax+1):
            done += 1
            progress(f'Mapový podklad: {done}/{total} dlaždic', done, total)
            tile = (fetch_osm_tile(z, x, y) if provider == 'OpenStreetMap'
                    else fetch_map_tile(z, x, y, provider))
            mosaic[(y-ymin)*256:(y-ymin+1)*256, (x-xmin)*256:(x-xmin+1)*256] = tile
    half = np.pi * 6378137.0
    span = 2 * half / 2**z
    source_transform = from_bounds(-half+xmin*span, half-(ymax+1)*span,
                                   -half+(xmax+1)*span, half-ymin*span,
                                   mosaic.shape[1], mosaic.shape[0])
    if viewport is None:
        view_extent = (-c.range_km, c.range_km, -c.range_km, c.range_km)
    else:
        view_extent = tuple(map(float, viewport))
    destination = np.zeros((4, height, width), dtype='uint8')
    reproject(np.moveaxis(mosaic, -1, 0), destination,
              src_transform=source_transform, src_crs='EPSG:3857',
              dst_transform=from_bounds(view_extent[0] * 1000, view_extent[2] * 1000,
                                        view_extent[1] * 1000, view_extent[3] * 1000,
                                        width, height),
              dst_crs=local_crs(c), resampling=Resampling.bilinear)
    return dict(image=np.moveaxis(destination, 0, -1),
                extent=view_extent, signature=(c.lat, c.lon, c.range_km), zoom=z,
                provider=provider, attribution=spec['attribution'])


# ========================================================================
# 3. VYKRESLENÍ MAPY A PROFILU
# ========================================================================

import numpy as np
from matplotlib.colors import ListedColormap, BoundaryNorm

def style_plot_axis(ax):
    """Jednotný profesionální tmavý vzhled technických grafů."""
    ax.set_facecolor(PLOT_BG)
    ax.tick_params(colors=UI_MUTED, labelsize=8, length=3, width=0.8)
    ax.xaxis.label.set_color(UI_MUTED)
    ax.yaxis.label.set_color(UI_MUTED)
    ax.title.set_color(UI_TEXT)
    ax.title.set_fontweight('semibold')
    for spine in ax.spines.values():
        spine.set_color(UI_BORDER_SOFT)
        spine.set_linewidth(0.8)
    ax.grid(color=UI_GRID, alpha=0.38, linewidth=0.7)

def style_legend(legend):
    if legend is None:
        return
    legend.get_frame().set_facecolor(UI_PANEL)
    legend.get_frame().set_edgecolor(UI_BORDER_SOFT)
    legend.get_frame().set_linewidth(0.8)
    legend.get_frame().set_alpha(0.95)
    for item in legend.get_texts():
        item.set_color(UI_TEXT)

def level_color(ft):
    return __import__('matplotlib').colormaps['turbo'](0.06 + 0.88 * np.log1p(ft / 1000) / np.log1p(66))

def map_plot(fig, result, mode='Krytí cíle', basemap=None, levels_ft=(), alpha=0.42,
             level_alphas=None):
    from matplotlib.lines import Line2D
    fig.clear()
    ax = fig.add_subplot(111)
    az, distance = result['az'], result['distance']
    c = result['config']
    sector = c.radar_mode == 'PAR-NG'
    da, dr = actual_azimuth_step(result), distance[0]
    ae = np.deg2rad(np.append(az - da / 2, az[-1] + da / 2))
    if sector:
        ae[0], ae[-1] = np.deg2rad(az[[0,-1]])
    re = np.r_[dr / 2, distance + dr / 2] / 1000
    if sector:
        re[-1] = c.range_km
    x, y = np.sin(ae)[:, None] * re, np.cos(ae)[:, None] * re
    if basemap is not None and basemap['signature'] == (c.lat, c.lon, c.range_km):
        ax.imshow(basemap['image'], extent=basemap['extent'], origin='upper', zorder=0)
        attribution = ax.text(0.99, 0.012, basemap_attribution(basemap),
                 ha='right', transform=ax.transAxes, fontsize=8, zorder=20,
                 color=UI_TEXT,
                 bbox=dict(facecolor=UI_PANEL, edgecolor=UI_BORDER, alpha=0.9))
        attribution.set_gid('basemap-attribution')
        attribution.set_url('https://www.arcgis.com/home/item.html?id=10df2279f9684e4a9f6a7f08febac2a9'
                            if basemap.get('provider') == 'Satelitní · Esri' else 'https://www.openstreetmap.org/copyright')
    if mode == 'Vybrané výšky' and levels_ft:
        # Draw unknown terrain once; every selected height has its own fill.
        # Filled contours preserve holes and avoid seams between polar cells.
        unknown = np.where(result['known'], np.nan, 1.0)
        ax.pcolormesh(x, y, np.ma.masked_invalid(unknown), cmap=ListedColormap(['#777777']),
                      alpha=0.3, shading='flat', rasterized=True)
        ac = np.deg2rad(az if sector else np.r_[az, 360])
        rc = (np.r_[dr/2, distance] if sector else np.r_[dr/2, distance, distance[-1]+dr/2]) / 1000
        xc, yc = np.sin(ac)[:, None]*rc, np.cos(ac)[:, None]*rc
        handles = []
        layers = {ft: status_at_height(result, ft * FT_TO_M) for ft in levels_ft}
        # Large areas below small ones, so opaque fills retain smaller regions.
        for ft in sorted(levels_ft, key=lambda h: np.count_nonzero(layers[h] == 1), reverse=True):
            data = layers[ft]
            # Padding closes known boundaries at the inner/outer sample edges.
            padded = (np.column_stack([data[:, :1], data]) if sector else
                      np.pad(np.vstack([data, data[:1]]), ((0, 0), (1, 1)), constant_values=0))
            has_coverage = np.any(data == 1)
            if has_coverage:
                opacity = float(np.clip((level_alphas or {}).get(ft, alpha), 0, 1))
                mesh = ax.contourf(xc, yc, np.ma.masked_invalid(padded),
                                   levels=[0.5, 1.5], colors=[level_color(ft)],
                                   alpha=opacity, antialiased=False, corner_mask=False, zorder=2)
                mesh.set_gid(f'height-fill-{ft}')
                ax.contour(xc, yc, np.ma.masked_invalid(padded), levels=[0.5],
                           colors=[level_color(ft)], linewidths=1.4, zorder=4)
            if len(handles) < 7:
                label = level_label(ft) + ('' if has_coverage else ' — bez krytí')
                handles.append(Line2D([0], [0], color=level_color(ft), lw=2, label=label))
        if len(levels_ft) > 7:
            handles.append(Line2D([], [], color='none', label=f'+ {len(levels_ft)-7} vrstev; barvy v seznamu'))
        style_legend(ax.legend(handles=handles, fontsize=7, loc='upper left', framealpha=0.9))
        title = f'Výškové řezy · {len(levels_ft)} vybraných · nominální ISA'
    elif mode == 'Vybrané výšky':
        title = 'Zaškrtni hladiny v legendě pod mapou'
    elif mode == 'Krytí cíle':
        cmap = ListedColormap([(0.4, 0.4, 0.4, 0.15), '#12a88a'])
        cmap.set_bad('#555e6c')
        ax.pcolormesh(x, y, np.ma.masked_invalid(result['status']), cmap=cmap,
                      norm=BoundaryNorm([-0.5, 0.5, 1.5], 2), alpha=alpha, shading='flat', rasterized=True)
        title = f'Cíl {c.target_m:g} m {c.reference} · zelená = krytí'
    else:
        data = result['lower'] if mode == 'Spodní hranice' else result['terrain']
        cmap = __import__('matplotlib').colormaps['viridis' if mode == 'Spodní hranice' else 'terrain'].copy()
        cmap.set_bad('#555e6c')
        mesh = ax.pcolormesh(x, y, np.ma.masked_invalid(data), cmap=cmap, alpha=max(0.25, alpha),
                             shading='flat', rasterized=True)
        fig.colorbar(mesh, ax=ax, pad=0.025, shrink=0.7, label='m AMSL')
        title = 'Spodní hranice krytí' if mode == 'Spodní hranice' else 'Vzorkovaný výškový model'
    if sector:
        outline = np.deg2rad(np.linspace(c.bearing_deg-20, c.bearing_deg+20, 161))
        ax.plot(np.r_[0, np.sin(outline)*40, 0], np.r_[0, np.cos(outline)*40, 0],
                color=UI_MUTED, linestyle='--', linewidth=0.8, zorder=5)
        title += f' · PAR-NG {c.bearing_deg:g}° ±20° / 40 km'
    ax.scatter([0], [0], marker='+', s=140, c=UI_TARGET, linewidths=2, zorder=5)
    ax.set(xlabel='Východ [km]', ylabel='Sever [km]', title=title, aspect='equal',
           xlim=(-c.range_km, c.range_km), ylim=(-c.range_km, c.range_km))
    ax.grid(alpha=0.15)
    if result.get('source') == 'SYNTHETIC DEMO':
        ax.text(0.5, 0.98, 'SYNTETICKÝ TERÉN — NE SKUTEČNÉ KRYTÍ', transform=ax.transAxes,
                ha='center', va='top', fontsize=8, color='#a32020',
                bbox=dict(facecolor=UI_PANEL, alpha=0.92, edgecolor=UI_BORDER))
    style_plot_axis(ax)
    for extra_ax in fig.axes:
        if extra_ax is not ax:
            style_plot_axis(extra_ax)
    fig.subplots_adjust(left=0.055, right=0.992, bottom=0.065, top=0.955)
    return ax

def point_detail(result, x_km, y_km, levels_ft=()):
    """Cursor coordinates; coverage comes from the nearest computed polar sample."""
    from pyproj import Geod
    c = result['config']
    radius = float(np.hypot(x_km, y_km))
    if not np.isfinite(radius) or radius > c.range_km:
        return 'Bod je mimo vypočtený dosah.'
    az = float(np.degrees(np.arctan2(x_km, y_km)) % 360)
    lon, lat, _ = Geod(ellps='WGS84').fwd(c.lon, c.lat, az, radius * 1000)
    location = f'{lat:.6f}°, {lon:.6f}°  ·  {radius:.2f} km / {radius/1.852:.2f} NM  ·  azimut {az:.1f}°'
    if radius * 1000 < result['distance'][0] / 2:
        return location + '\nStanoviště / oblast před prvním vzorkem — krytí není vzorkováno.'
    ai, inside = azimuth_indices(result['az'], c, az)
    if not inside:
        return location + '\nBod je mimo vypočtený sektor PAR-NG ±20°.'
    ai = int(ai)
    ri = int(np.argmin(np.abs(result['distance'] - radius * 1000)))
    terrain, lower = result['terrain'][ai, ri], result['lower'][ai, ri]
    fmt = lambda v: f'{v:.0f} m' if np.isfinite(v) else 'neznámá'
    detail = f'Terén {fmt(terrain)} AMSL  ·  spodní hranice {fmt(lower)} AMSL'
    if np.isfinite(lower) and np.isfinite(terrain):
        detail += f' / {lower-terrain:.0f} m AGL'
    # Slice once: never evaluate an entire coverage raster on mouse movement.
    cell = dict(result)
    for key in ('terrain', 'lower', 'upper', 'known'):
        cell[key] = result[key][ai:ai+1, ri:ri+1]
    cell['distance'] = result['distance'][ri:ri+1]
    if not result['known'][ai, ri]:
        state = 'Krytí neznámé — chybí data terénního profilu.'
    elif levels_ft:
        visible = [level_label(ft) for ft in levels_ft
                   if status_at_height(cell, ft * FT_TO_M)[0, 0] == 1]
        state = 'Kryté vybrané hladiny: ' + (', '.join(visible) or 'žádné')
    else:
        state = f'Cíl {c.target_m:g} m {c.reference}: ' + (
            'KRYTÝ' if result['status'][ai, ri] == 1 else 'NEKRYTÝ / mimo meze')
    return location + '\n' + detail + '\n' + state + f'  ·  vzorek {result["az"][ai]:.1f}° / {result["distance"][ri]/1000:.2f} km'


def export_map_image(path, result, mode, basemap=None, levels_ft=(), alpha=0.42,
                     level_alphas=None, limits=None, dpi=300):
    """Render a fresh print-size figure, not a screen capture."""
    from matplotlib.backends.backend_agg import FigureCanvasAgg
    from matplotlib.lines import Line2D
    if dpi not in (300, 600):
        raise ValueError('Export podporuje 300 nebo 600 DPI.')
    fig = Figure(figsize=(13, 9), dpi=dpi, facecolor=PLOT_BG)
    FigureCanvasAgg(fig)
    try:
        ax = map_plot(fig, result, mode, basemap, levels_ft, alpha, level_alphas)
        if limits is not None:
            ax.set_xlim(limits[0])
            ax.set_ylim(limits[1])
        if ax.get_legend() is not None:
            ax.get_legend().remove()
        fig.subplots_adjust(left=0.075, right=0.75, bottom=0.25, top=0.90)
        handles = []
        if mode == 'Vybrané výšky':
            handles = [Line2D([], [], color=level_color(ft), lw=3, label=level_label(ft)) for ft in levels_ft]
        elif mode == 'Krytí cíle':
            handles = [Line2D([], [], color='#12a88a', lw=5, label='Geometrické krytí'),
                       Line2D([], [], color='#777777', lw=5, label='Neznámá data')]
        if handles:
            legend = fig.legend(handles=handles, loc='upper left',
                                bbox_to_anchor=(0.77, 0.88), fontsize=9, title='Legenda')
            style_legend(legend)
            legend.get_title().set_color(UI_TEXT)
        c = result['config']
        fig.text(0.075, 0.955, 'ELDIS · RADAR COVERAGE', color=UI_TEXT, fontsize=18, weight='bold')
        fig.text(0.075, 0.105,
                 f'Radar: {c.lat:.6f}°, {c.lon:.6f}°  |  Anténa: {c.antenna_agl:g} m AGL  |  Dosah: {c.range_km:g} km\n'
                 f'k = {c.k:.3f}  |  Elevace: {c.min_elev:g}–{c.max_elev:g}°  |  Tilt: {c.antenna_tilt_deg:g}°  |  '
                 f'Síť: {c.step_m:g} m / {actual_azimuth_step(result):g}°\n'
                 f'Geometrický model · výškové řezy AMSL · {dpi} DPI · 330 × 229 mm',
                 color=UI_TEXT, fontsize=9, linespacing=1.6)
        fig.text(0.075, 0.035, 'Rozlišení terénu a mapového podkladu odpovídá zdrojovým datům.',
                 color=UI_MUTED, fontsize=8)
        fig.savefig(path, dpi=dpi, format='png', facecolor=fig.get_facecolor())
    finally:
        fig.clear()



def antenna_plot(gain_ax, envelope_ax, c, antenna, levels_ft=(), pattern=None):
    e = np.linspace(np.deg2rad(c.min_elev), np.deg2rad(c.max_elev), 600)
    pair = isinstance(pattern, AntennaPatternPair)

    if pair:
        low_db, high_db = pattern.channel_gain_db(e, c.antenna_tilt_deg)
        diagram_title = f'Dual beam · {pattern.name}'
        detail = (f'mode = {c.beam_mode} · tilt = {c.antenna_tilt_deg:+g}° · '
                  f'L_ref LOW = {c.csc_range_km:g} km\n'
                  f'LOW {pattern.low_peak_dbi:g} dBi Tx/Rx · HIGH {pattern.high_peak_dbi:g} dBi Rx-only')
        gain_ax.plot(np.rad2deg(e), low_db, color=UI_ACCENT, lw=2, label='LOW · Tx/Rx')
        gain_ax.plot(np.rad2deg(e), high_db, color=UI_TARGET, lw=2, label='HIGH · Rx only')
        gain_ax.legend(loc='lower right', fontsize=7)
        finite_gain = np.r_[low_db[np.isfinite(low_db) & (low_db > -199)],
                            high_db[np.isfinite(high_db) & (high_db > -199)]]
    elif pattern is None:
        gain_db = 10 * np.log10(csc_gain(e, c))
        diagram_title = 'Idealizovaný diagram · csc²'
        detail = f'e_ref = {c.csc_ref_deg:g}° · L_ref = {c.csc_range_km:g} km'
        gain_ax.axvline(c.csc_ref_deg + c.antenna_tilt_deg,
                        color=UI_MUTED, ls='--', lw=1)
        gain_ax.plot(np.rad2deg(e), gain_db, color=UI_ACCENT, lw=2)
        finite_gain = gain_db[np.isfinite(gain_db) & (gain_db > -199)]
    else:
        gain_db = pattern.gain_db(e, c.antenna_tilt_deg)
        diagram_title = f'Single beam · {pattern.name}'
        detail = f'tilt = {c.antenna_tilt_deg:+g}° · L_ref = {c.csc_range_km:g} km'
        gain_ax.plot(np.rad2deg(e), gain_db, color=UI_ACCENT, lw=2)
        finite_gain = gain_db[np.isfinite(gain_db) & (gain_db > -199)]

    gain_ax.set(title=diagram_title, xlabel='Elevace [°]',
                ylabel='Normalizovaný zisk [dB]')
    gain_ax.grid(alpha=0.2)
    if finite_gain.size:
        gain_ax.set_ylim(max(-60, float(np.min(finite_gain)) - 3), 3)
    gain_ax.text(0.03, 0.04, detail + '\n'
                 + ('DIAGRAM VE VÝPOČTU' if c.csc_enabled else 'POUZE NÁHLED'),
                 transform=gain_ax.transAxes, fontsize=8,
                 color=UI_TEXT,
                 bbox=dict(facecolor=UI_PANEL, edgecolor=UI_BORDER, alpha=0.9))

    distance = np.linspace(1, c.range_km * 1000, 900)
    bottom = height_at_angle(distance, np.deg2rad(c.min_elev), antenna, c.k)
    top = height_at_angle(distance, np.deg2rad(c.max_elev), antenna, c.k)
    good = np.isfinite(top) & (top >= bottom)

    if c.csc_enabled and pattern is not None:
        heights_ft = np.linspace(0, 70000, 280)
        target = heights_ft[:, None] * FT_TO_M
        if pair:
            low_allowed = pattern_allows(distance[None, :], target, antenna, c, pattern, 'LOW')
            high_allowed = pattern_allows(distance[None, :], target, antenna, c, pattern, 'HIGH')
            if c.beam_mode == 'LOW':
                allowed = low_allowed
            elif c.beam_mode == 'HIGH':
                allowed = high_allowed
            else:
                allowed = low_allowed | high_allowed
                # Show channel boundaries as context; union remains the actual model.
                envelope_ax.contour(distance / 1000, heights_ft, low_allowed.astype(float),
                                    levels=[0.5], colors=[UI_ACCENT], linewidths=0.8, alpha=0.9)
                envelope_ax.contour(distance / 1000, heights_ft, high_allowed.astype(float),
                                    levels=[0.5], colors=[UI_TARGET], linewidths=0.8, alpha=0.9)
            envelope_ax.contourf(distance / 1000, heights_ft, allowed.astype(float),
                                 levels=[0.5, 1.5], colors=[UI_ACCENT], alpha=0.24)
        else:
            allowed = pattern_allows(distance[None, :], target, antenna, c, pattern)
            envelope_ax.contourf(distance / 1000, heights_ft, allowed.astype(float),
                                 levels=[0.5, 1.5], colors=[UI_ACCENT], alpha=0.28)
    elif c.csc_enabled and pattern is None:
        heights_ft = np.linspace(0, 70000, 280)
        allowed = csc_allows(distance[None, :], heights_ft[:, None] * FT_TO_M, antenna, c)
        envelope_ax.contourf(distance / 1000, heights_ft, allowed.astype(float),
                             levels=[0.5, 1.5], colors=[UI_ACCENT], alpha=0.28)
    else:
        envelope_ax.fill_between(distance / 1000, bottom / FT_TO_M, top / FT_TO_M,
                                 where=good, color=UI_ACCENT, alpha=0.25)
        envelope_ax.plot(distance / 1000, np.where(good, top / FT_TO_M, np.nan),
                         color=UI_ACCENT, lw=1.7)

    envelope_ax.plot(distance / 1000, bottom / FT_TO_M, color=UI_ACCENT, lw=1)
    for ft in levels_ft:
        envelope_ax.axhline(ft, color=level_color(ft), lw=0.9, alpha=0.85)
    if isinstance(pattern, GenericSSRPattern):
        for angle in (0, 1, 2, 5, 10, 20):
            ray = height_at_angle(distance, np.deg2rad(angle), antenna, c.k) / FT_TO_M
            envelope_ax.plot(distance / 1000, ray, color=UI_MUTED, lw=.55, ls=':', alpha=.6)
            visible_ray = np.flatnonzero((ray >= 0) & (ray <= 66000))
            if visible_ray.size:
                j = visible_ray[-1]
                envelope_ax.text(distance[j]/1000, ray[j], f'{angle}°', fontsize=6, color=UI_MUTED,
                                 ha='right', va='bottom')
    envelope_ax.set(title=('SSR · Blakeův diagram · bez terénu' if isinstance(pattern, GenericSSRPattern)
                           else 'Použitá anténní obálka bez terénu'),
                    xlabel='Povrchová vzdálenost [km]', ylabel='Výška [ft AMSL]',
                    xlim=(0, c.range_km), ylim=(0, 70000))
    envelope_ax.grid(alpha=0.2)
    if pair:
        model_note = ('RL-2000 dual beam: LOW Tx/Rx + HIGH Rx-only · '
                      f'výpočet {c.beam_mode}')
    elif isinstance(pattern, GenericSSRPattern):
        model_note = 'Obecný SSR · 1030/1090 MHz · limit 256 NM\nIdealizované předpoklady; bez multipath / Pd'
    elif pattern is not None:
        model_note = 'Načtený single-beam diagram · maximum 0 dB'
    else:
        model_note = 'Idealizovaný single-beam csc² model'
    envelope_ax.text(0.02, 0.97, model_note, va='top', transform=envelope_ax.transAxes,
                     color=UI_TEXT, fontsize=7,
                     bbox=dict(facecolor=UI_PANEL, edgecolor=UI_BORDER, alpha=0.88))
    style_plot_axis(gain_ax)
    style_plot_axis(envelope_ax)
    style_legend(gain_ax.get_legend())


def technical_plot(fig, result=None, levels_ft=(), config=None, pattern=None):
    """Samostatný technický panel: diagram antény a použitá obálka."""
    fig.clear()
    layout = fig.add_gridspec(2, 1, hspace=0.62)
    gain_ax = fig.add_subplot(layout[0, 0])
    envelope_ax = fig.add_subplot(layout[1, 0])
    if result is None:
        c = config or Config()
        antenna = 200.0 + c.antenna_agl
    else:
        c = result['config']
        antenna = result['antenna']
        pattern = result.get('antenna_pattern')
    antenna_plot(gain_ax, envelope_ax, c, antenna, levels_ft,
                 pattern)
    for ax in (gain_ax, envelope_ax):
        ax.tick_params(labelsize=7)
        ax.title.set_fontsize(10)
        ax.xaxis.label.set_size(8)
        ax.yaxis.label.set_size(8)
    fig.subplots_adjust(left=0.20, right=0.97, bottom=0.11, top=0.94)
    return gain_ax, envelope_ax

def profile_plot(fig, result, index=0, selected=None, levels_ft=()):
    fig.clear()
    ax = fig.add_subplot(111)
    d = result['distance'] / 1000
    ax.plot(d, result['terrain'][index] / FT_TO_M, color=UI_MUTED, lw=1, label='Terén')
    ax.plot(d, result['lower'][index] / FT_TO_M, color=UI_ACCENT, lw=1.8, label='Spodní hranice')
    upper = result['upper'][index] / FT_TO_M
    ax.plot(d, np.where(np.isfinite(upper), upper, np.nan), color=UI_RX_COLORS[2], lw=1, label='Horní hranice')
    if levels_ft:
        for ft in levels_ft:
            ax.axhline(ft, color=level_color(ft), lw=0.9, alpha=0.85)
    else:
        ax.plot(d, result['target'][index] / FT_TO_M, color=UI_TARGET, ls='--', label='Cíl')
    ax.scatter([0], [result['antenna'] / FT_TO_M], color=UI_TARGET, s=24)
    if selected is not None:
        ax.axvline(selected, color=UI_ESTIMATE, lw=0.9)
    displayed_height = max(levels_ft) if levels_ft else float(np.nanmax(result['target']) / FT_TO_M)
    ax.set(xlabel='Povrchová vzdálenost [km]', ylabel='Výška [ft AMSL]',
           ylim=(min(0, np.nanmin(result['terrain'][index])/FT_TO_M) if np.any(np.isfinite(result['terrain'][index])) else 0,
                 min(100000, max(5000, displayed_height * 1.2))),
           title=f'Profil · azimut {result["az"][index]:.1f}° · k = {result["config"].k:.3f}')
    style_plot_axis(ax)
    style_legend(ax.legend(loc='upper left', fontsize=8, ncol=2))
    fig.tight_layout(pad=0.8)
    return ax

