def clamp_view_limits(xlim, ylim, radius):
    """Čistá, testovatelná geometrie omezení interaktivní mapy."""
    if not np.isfinite(radius) or radius <= 0:
        raise ValueError('Poloměr mapové oblasti musí být kladný.')
    minimum_span = max(0.2, radius / 100.0)
    def clamp_one(limits):
        lo, hi = sorted(map(float, limits))
        span = min(2 * radius, max(minimum_span, hi - lo))
        centre = (lo + hi) / 2
        half = span / 2
        centre = min(radius - half, max(-radius + half, centre))
        return centre - half, centre + half
    return clamp_one(xlim), clamp_one(ylim)

def navigation_limits(xlim, ylim, aspect=None):
    """Map navigation is independent of radar coverage; regional AEQD domain."""
    values = np.asarray((*xlim, *ylim), dtype=float)
    if not np.all(np.isfinite(values)):
        raise ValueError('Neplatný výřez mapy.')
    x0, x1 = sorted(xlim)
    y0, y1 = sorted(ylim)
    cx, cy = (x0+x1)/2, (y0+y1)/2
    sx, sy = max(0.2, x1-x0), max(0.2, y1-y0)
    if aspect is not None:
        aspect = max(0.1, float(aspect))
        sx = max(sx, sy * aspect)
        sy = sx / aspect
    scale = min(1.0, 12000.0 / max(sx, sy))
    sx, sy = sx*scale, sy*scale
    cx = float(np.clip(cx, -6000+sx/2, 6000-sx/2))
    cy = float(np.clip(cy, -6000+sy/2, 6000-sy/2))
    return ((cx-sx/2, cx+sx/2), (cy-sy/2, cy+sy/2))


def preview_affine(source_limits, target_limits, size):
    """Pillow inverse transform: output pixel -> original map snapshot pixel."""
    (sx0, sx1), (sy0, sy1) = source_limits
    (tx0, tx1), (ty0, ty1) = target_limits
    width, height = size
    return ((tx1-tx0)/(sx1-sx0), 0, (tx0-sx0)*width/(sx1-sx0),
            0, (ty1-ty0)/(sy1-sy0), (sy1-ty1)*height/(sy1-sy0))


