        ctk.CTkLabel(levels_body, height=22, text='Vybrané výškové hladiny · 500–66 000 ft · AMSL',
                     anchor='w', text_color=TEXT_SECONDARY,
                     font=ctk.CTkFont(size=11)).pack(fill='x', pady=(0, 6))
        level_actions = ctk.CTkFrame(levels_body, fg_color='transparent')
