    def test_vectorized_sample_matches_point_sampler(self):
        import rasterio
        from rasterio.transform import from_origin
        from pyproj import Geod, Transformer
        c = replace(self.c, range_km=1.5, step_m=150, az_step=5, lat=0, lon=0)

        def reference_sample(path):
            az, distance = axes(c)
            geod = Geod(ellps='WGS84')
            output = np.full((len(az), len(distance)), np.nan)
            with rasterio.open(path) as ds:
                transform = Transformer.from_crs('EPSG:4326', ds.crs, always_xy=True)
                scale, offset = ds.scales[0], ds.offsets[0]
                def values(x, y):
                    sampled = np.ma.vstack(list(ds.sample(
                        zip(np.atleast_1d(x), np.atleast_1d(y)),
                        indexes=1, masked=True)))[:, 0]
                    return sampled.astype(float).filled(np.nan) * scale + offset
                x0, y0 = transform.transform(c.lon, c.lat)
                ground = float(values(x0, y0)[0])
                for i, angle in enumerate(az):
                    lon, lat, _ = geod.fwd(
                        np.full_like(distance, c.lon), np.full_like(distance, c.lat),
                        np.full_like(distance, angle), distance)
                    x, y = transform.transform(lon, lat)
                    output[i] = values(x, y)
            return output, ground

        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'gradient.tif'
            height = width = 160
            data = (np.arange(height)[:, None] * 1000
                    + np.arange(width)[None, :]).astype('float32')
            with rasterio.open(
                    path, 'w', driver='GTiff', count=1, width=width, height=height,
                    dtype='float32', crs='EPSG:4326', nodata=-9999,
                    transform=from_origin(-0.024, 0.024, 0.0003, 0.0003),
                    tiled=True, blockxsize=32, blockysize=32) as ds:
                ds.write(data, 1)
            actual, actual_site = sample(path, c)
            expected, expected_site = reference_sample(path)
        np.testing.assert_allclose(actual, expected, equal_nan=True)
        self.assertEqual(actual_site, expected_site)

