    def test_cosecant_envelope_matches_slant_definition(self):
        c = replace(self.c, csc_enabled=True, csc_range_km=15, csc_ref_deg=5,
                    min_elev=0, max_elev=80)
        result = solve(c, self.flat, 200)
        d = result['distance']

        # Exported `upper` is now always the geometric max-elevation envelope.
        geometric_upper = height_at_angle(d, np.deg2rad(c.max_elev),
                                          result['antenna'], c.k)
        np.testing.assert_allclose(result['upper'],
                                   np.broadcast_to(geometric_upper, result['upper'].shape))

        # Actual visibility still includes the built-in csc² range restriction.
        target = result['target']
        e = apparent_angle(d, target, result['antenna'], c.k)
        direct = (result['known']
                  & (e >= np.maximum(result['horizon'], np.deg2rad(c.min_elev)))
                  & (e <= np.deg2rad(c.max_elev))
                  & csc_allows(d[None, :], target, result['antenna'], c))
        np.testing.assert_equal(result['status'],
                                np.where(result['known'], direct.astype(float), np.nan))


