    def test_basemap_reprojection_center(self):
        # A known longitude/latitude landmark maps to the radar center after warping.
        c = replace(self.c, lat=50, lon=15, range_km=20)
        z, x0, x1, y0, y1 = tile_plan(c)
        n = 2**z
        center_x = (c.lon+180)/360*n*256
        center_y = (1-np.arcsinh(np.tan(np.deg2rad(c.lat)))/np.pi)/2*n*256
        def synthetic_tile(z, x, y):
            xx, yy = np.meshgrid(np.arange(256)+x*256, np.arange(256)+y*256)
            pixels = np.zeros((256, 256, 4), dtype='uint8')
            pixels[:, :, 3] = 255
            pixels[np.hypot(xx-center_x, yy-center_y)<10, 0] = 255
            return pixels
        with patch(__name__ + '.fetch_osm_tile', side_effect=synthetic_tile):
            layer = load_basemap(c)
        self.assertEqual(layer['signature'], (50, 15, 20))
        self.assertEqual(layer['image'].shape, (1000, 1000, 4))
        self.assertGreater(layer['image'][500, 500, 0], 200)

    def test_basemap_uses_current_viewport_and_resolution(self):
        c = replace(self.c, lat=50, lon=15, range_km=100)
        viewport = (-8.0, 12.0, -5.0, 7.0)
        full_zoom = tile_plan(c)[0]
        view_zoom, x0, x1, y0, y1 = tile_plan(c, viewport, 800)
        self.assertGreaterEqual(view_zoom, full_zoom)
        self.assertLessEqual((x1-x0+1)*(y1-y0+1), 36)

        tile = np.zeros((256, 256, 4), dtype='uint8')
        tile[:, :, :3] = 120
        tile[:, :, 3] = 255
        with patch(__name__ + '.fetch_osm_tile', return_value=tile):
            layer = load_basemap(c, viewport=viewport, out_size=(640, 400))
        self.assertEqual(layer['extent'], viewport)
        self.assertEqual(layer['image'].shape, (400, 640, 4))
        self.assertEqual(layer['zoom'], view_zoom)



