    def test_raster_gpkg_can_replace_existing_file(self):
        import rasterio
        c = replace(self.c, range_km=2, step_m=250, az_step=5)
        az, distance = axes(c)
        result = solve(c, np.full((len(az), len(distance)), 200.0), 200)
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'coverage.gpkg'
            try:
                first = export_gpkg_raster(path, result, (1000,))
                second = export_gpkg_raster(path, result, (1000,))
            except ValueError as exc:
                if 'nepodporuje GeoPackage' in str(exc):
                    self.skipTest(str(exc))
                raise
            self.assertEqual(first, second)
            with rasterio.open(path) as ds:
                self.assertEqual(len(ds.subdatasets), second)

    def test_native_vector_holes_and_raw_roundtrip(self):
        try:
            from shapely import wkb
        except ImportError:
            self.skipTest('shapely not installed')
        import sqlite3
        c=Config(range_km=10,step_m=250,az_step=2)
        az,d=axes(c)
        r=solve(c,np.full((len(az),len(d)),200.),200)
        polygons=coverage_polygons(r,np.ones_like(r['status']))
        self.assertEqual(len(polygons),1)
        self.assertEqual(len(polygons[0].interiors),1)
        self.assertTrue(polygons[0].is_valid)
        self.assertGreater(polygons[0].area,3.1e8)
        status=np.ones_like(r['status']); status[30:40,10:20]=np.nan
        cut=coverage_polygons(r,status)
        self.assertLess(sum(p.area for p in cut),polygons[0].area)
        with tempfile.TemporaryDirectory() as tmp:
            path=Path(tmp)/'vectors.gpkg'
            self.assertEqual(export_gpkg(path,r,(1000,66000)),6)
            from contextlib import closing
            with closing(sqlite3.connect(path)) as db:
                layers=db.execute('SELECT table_name FROM gpkg_geometry_columns').fetchall()
                self.assertEqual(len(layers),6)
                for (name,) in layers:
                    for (blob,) in db.execute(f'SELECT geom FROM "{name}"'):
                        self.assertTrue(wkb.loads(blob[8:]).is_valid)
            raw=Path(tmp)/'raw.npz'
            export_raw_npz(raw,r)
            with np.load(raw,allow_pickle=False) as data:
                np.testing.assert_equal(data['terrain'],r['terrain'])
                np.testing.assert_equal(data['status'],r['status'])


